def transform(grid):
    h, w = len(grid), len(grid[0])

    # Full lines of a non-background color divide the grid into compartments.
    line_color = None
    for r in range(h):
        if len(set(grid[r])) == 1:
            line_color = grid[r][0]
            break
    if line_color is None:
        return [row[:] for row in grid]

    sep_rows = [r for r in range(h) if all(v == line_color for v in grid[r])]
    sep_cols = [c for c in range(w) if all(grid[r][c] == line_color for r in range(h))]

    def ranges(n, separators):
        result = []
        start = 0
        for p in separators:
            if start < p:
                result.append((start, p))
            start = p + 1
        if start < n:
            result.append((start, n))
        return result

    row_parts = ranges(h, sep_rows)
    col_parts = ranges(w, sep_cols)

    # The most common non-divider color is the compartment background.
    counts = {}
    for row in grid:
        for v in row:
            if v != line_color:
                counts[v] = counts.get(v, 0) + 1
    if not counts:
        return [row[:] for row in grid]
    background = max(counts, key=counts.get)

    out = [row[:] for row in grid]
    source = None
    for r0, r1 in row_parts:
        for c0, c1 in col_parts:
            cells = [(r, c) for r in range(r0, r1) for c in range(c0, c1)
                     if grid[r][c] != background]
            if cells:
                minr = min(r for r, c in cells)
                maxr = max(r for r, c in cells)
                minc = min(c for r, c in cells)
                maxc = max(c for r, c in cells)
                source = [[grid[r][c] for c in range(minc, maxc + 1)]
                          for r in range(minr, maxr + 1)]
                break
        if source is not None:
            break

    if source is None:
        return out

    for r0, r1 in row_parts:
        for c0, c1 in col_parts:
            for dr in range(min(len(source), r1 - r0)):
                for dc in range(min(len(source[0]), c1 - c0)):
                    out[r0 + dr][c0 + dc] = source[dr][dc]
    return out
